UPDATE material_translations SET body='{"captions":["relief fluvial – eroziune laterală (1), în adâncime (2) și acumulare (3)","relief fluvial – transportul aluviunilor (suspensie, soluție, târâre, saltație)","relief fluvial – elementele unei văi (albie minoră, luncă, terase, talveg)","relief de pluviodenudare – formarea rigolelor prin șiroire pe versant","relief gravitațional – elementele unei alunecări de teren (râpă, corp, pat, frunte)","relief gravitațional – alunecare de teren peste o așezare (vedere aeriană)","relief gravitațional – tasare și sufoziune în loess (crovuri, hornuri, tuneluri)","relief glaciar – elementele componente ale unei văi glaciare (circ, bazinet, prag, morene)","relief glaciar – circ glaciar","relief glaciar – vale glaciară în formă de U","relief glaciar – custură (creastă ascuțită)","relief glaciar – fiord (vale glaciară invadată de mare)","relief deșertic – dune de nisip","relief deșertic – ciupercă eoliană (modelată prin coraziune)","relief deșertic – inselberg (Uluru, Australia)","relief deșertic – hamada/reg (deșert pietros)","relief litoral – țărm cu fiorduri (Norvegia)","relief litoral – țărm cu rias (Spania)","relief litoral – țărm dalmatic (Croația)","relief litoral – faleză înaltă modelată prin abraziune (Cliffs of Moher)","relief fluvio-maritim – deltă (Delta Padului, Italia)","relief carstic – schema formelor carstice (lapiezuri, doline, uvale, polii, peșteri)","relief carstic – peșteră cu stalactite (1), coloane (2) și stalagmite (3)","relief vulcanic – coloane de bazalt (Racoș)","relief pe conglomerate – Sfinxul (Bucegi)","relief pe argile – badlands / pământuri rele (Râpa Roșie)","relief pe roci magmatice – căpățână de zahăr (granit, climat cald și umed)","relief structural – canion pe structură tabulară (strate orizontale)","relief structural – cuestă cu frunte și spinare (structură monoclinală)","relief structural – cueste și văi pe structură monoclinală (schemă)","relief structural – horst și graben (structură faliată)","